 285→// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
 286→function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
 287→  if (!rawCss) return "";
 288→  const css = rawCss.replace(/<\/style>/gi, "");
 289→  let result = "";
 290→  let remaining = css;
 291→  while (remaining.length > 0) {
 292→    const openBrace = remaining.indexOf("{");
 293→    if (openBrace === -1) break;
 294→    const closeBrace = remaining.indexOf("}", openBrace);
 295→    if (closeBrace === -1) break;
 296→    const selector = remaining.substring(0, openBrace).trim();
 297→    const body = remaining.substring(openBrace + 1, closeBrace);
 298→    remaining = remaining.substring(closeBrace + 1);
 299→    if (selector.startsWith("@")) {
 300→      result += selector + "{" + body + "}";
 301→    } else if (selector) {
 302→      const prefixed = selector.split(",").map(s => {
 303→        s = s.trim();
 304→        return s ? "#" + wid + " " + s : "";
 305→      }).filter(Boolean).join(", ");
 306→      result += prefixed + " {" + body + "}";
 307→    }
 308→  }
 309→  return result;
 310→}
