 380→    W + " .zcc-result.fail .zcc-result-icon svg{color:" + e + ";stroke:" + e + "}" +
 381→    W + " .zcc-wl{margin-top:10px;padding:13px 14px;background:#f8fafc;border-radius:10px;border:1px solid #e2e8f0}" +
 382→    W + " .zcc-wl-input{border-radius:8px;border:1.5px solid #dee2e6;padding:10px 14px;width:100%;display:block;margin-bottom:8px;outline:none;font-size:13px;transition:border-color 0.2s,box-shadow 0.2s;background:#fff;color:" + cfg.textColor + "}" +
 383→    W + " .zcc-wl-btn{border-radius:" + btnRadius + ";background:" + p + ";color:#fff;padding:10px 20px;width:100%;font-weight:600;border:none;cursor:pointer;font-size:13px;transition:filter 0.2s,box-shadow 0.2s,transform 0.2s;letter-spacing:0.01em;box-shadow:0 2px 8px " + p + "25;display:flex;align-items:center;justify-content:center;gap:6px}" +
 384→    W + " .zcc-wl-btn:hover{filter:brightness(1.06);box-shadow:0 4px 14px " + p + "40;transform:translateY(-1px)}" +
 385→    W + " .zcc-wl-btn:active{filter:brightness(0.95);transform:translateY(0)}" +
 386→    buildSharedMetaCss(W, cfg);
 387→  return base + scopeAdminCss(cfg.customCss, wid);
